{"test_code":"from pager.pagination import page_slice, total_pages


def test_total_pages_rounds_up_for_partial_last_page() -> None:
    assert total_pages(10, 3) == 4


def test_last_partial_page_contains_final_item() -> None:
    items = list(range(1, 11))
    assert page_slice(items, 4, 3) == [10]
","rationale":"With 10 items and 3 per page, total_pages should be 4 (partial last page), and page 4 should return the last item; the buggy floor division gives 3 and raises PageOutOfRange."}
